import sqlite3
from contextlib import closing

class NotasDAL:
    def __init__(self, ruta):
        self.ruta = ruta
        with closing(sqlite3.connect(ruta)) as conn, conn:
            conn.execute("""
                CREATE TABLE IF NOT EXISTS notas (
                    id INTEGER PRIMARY KEY,
                    texto TEXT NOT NULL,
                    tag TEXT NOT NULL
                )""")

    def agregar_varias(self, notas):
        with closing(sqlite3.connect(self.ruta)) as conn, conn:
            conn.executemany(
                "INSERT INTO notas (texto, tag) VALUES (?, ?)", notas)

    def buscar(self, termino, limite=100):
        with closing(sqlite3.connect(self.ruta)) as conn:
            return conn.execute(
                "SELECT * FROM notas WHERE texto LIKE ? LIMIT ?",
                (f'%{termino}%', limite)
            ).fetchall()

    def borrar(self, nota_id) -> bool:
        with closing(sqlite3.connect(self.ruta)) as conn, conn:
            cur = conn.execute("DELETE FROM notas WHERE id = ?", (nota_id,))
            return cur.rowcount > 0   # False si no existía: verdad, no mentira

